mapper.select:
SELECT
FROM flow_task_node tn INNER JOIN flow_task t ON tn.task_id = t.id LEFT JOIN flow_template tpl ON t.template_id = tpl.id LEFT JOIN flow_task_dispatch_node dn ON tn.dispatch_node_id = dn.id LEFT JOIN flow_template_node n ON tn.node_id = n.id LEFT JOIN flow_task_dispatch d ON d.id = t.dispatch_id WHERE tn.handler_user_id = #{handlerUserId} AND t.status IN ('进行中', '已结束')
AND tn.id = ( SELECT MAX(t2.id) FROM flow_task_node t2 WHERE t2.task_id = tn.task_id AND t2.handler_user_id = #{handlerUserId} ) ORDER BY tn.create_time DESC LIMIT #{offset}, #{limit}

SELECT , COALESCE(d.task_id, t.id) AS plan_id FROM flow_task_node tn INNER JOIN flow_task t ON tn.task_id = t.id LEFT JOIN flow_template tpl ON t.template_id = tpl.id LEFT JOIN flow_task_dispatch_node dn ON tn.dispatch_node_id = dn.id LEFT JOIN flow_template_node n ON tn.node_id = n.id LEFT JOIN flow_task_dispatch d ON d.id = t.dispatch_id WHERE tn.handler_user_id = #{handlerUserId} AND t.status IN ('进行中', '已结束') AND COALESCE(d.task_id, t.id) IN
#{taskId}
AND tn.id = ( SELECT MAX(t2.id) FROM flow_task_node t2 WHERE t2.task_id = tn.task_id AND t2.handler_user_id = #{handlerUserId} ) ORDER BY tn.create_time DESC
